guided_steps.solution:
class Student:
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def introduce(self):
        return "私は" + self.name + "です。" + str(self.age) + "歳です。"

student = Student("太郎", 20)
print(student.introduce())

challenges.solution:
class BankAccount:
    def __init__(self, balance):
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount

    def withdraw(self, amount):
        self.balance -= amount

    def show_balance(self):
        print("残高: " + str(self.balance) + "円")

account = BankAccount(1000)
account.deposit(500)
account.withdraw(300)
account.show_balance()

free_practices.exampleSolution:
class Pet:
    def __init__(self, name, species, age):
        self.name = name
        self.species = species
        self.age = age

    def bark(self):
        if self.species == "犬":
            return "ワンワン!"
        elif self.species == "猫":
            return "ニャー!"
        else:
            return "..."

my_pet = Pet("ポチ", "犬", 3)
print(my_pet.name + ": " + my_pet.bark())
